export const defaults={company:'Mein Dienstleistungsbetrieb',owner:'',address:'',email:'',phone:'',website:'',offerFooter:'',serviceRates:{},taxId:'',iban:'',tax:0,taxMode:'small',businessStart:'',watchYear:new Date().getFullYear(),previousTurnover:0,externalTurnover:0,reservePercent:25,hourlyCost:24,overhead:7,targetMargin:25,kmCost:.45,travelHourlyRate:45,travelKmRate:.65,paymentDays:14,quotePrefix:'ANG',quoteDays:30,nextQuoteNumber:1,currency:'EUR',country:'Deutschland',homeBase:'96268 Mitwitz',serviceArea:'Kronach, Sonnefeld, Stockheim, Gundelsdorf',region:'Bayern',disposalRate:0,transportHourlyRate:45,speech:false,voiceURI:'',speechRate:1.08,shortVoice:true,voiceAutoSubmit:true,handsFree:false};
export const money=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(Number(n)||0);
export const number=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(Number(n)||0);
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
export const dateText=d=>d?new Intl.DateTimeFormat('de-DE',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'Kein Termin';
export const uid=()=>crypto.randomUUID();
export function calculate(job,settings=defaults){
 const costsSettings={...defaults,...settings,...job.costSettings};
 const factor=Number(job.factor)||1; let serviceNet=0,hours=0,consumables=0;
 for(const l of job.lines||[]){const s=services.find(s=>s.id===l.service);if(!s)continue;const qty=Math.max(0,Number(l.qty)||0);serviceNet=roundMoney(serviceNet+roundMoney(qty*Math.max(0,Number(l.rate)||0)));hours+=qty*(l.minutes??s.minutes)/60*factor;consumables+=job.resourceCostsApplied===true?0:qty*s.material*factor}
 hours+=Math.max(0,Number(job.travelHours)||0)+Math.max(0,Number(job.setupHours)||0);
 const travelCost=Math.max(0,Number(job.km)||0)*(Number(costsSettings.kmCost)||0);
 const extraCost=roundMoney([job.material,job.disposal,job.rental].reduce((sum,value)=>sum+roundMoney(Math.max(0,Number(value)||0)),0));
 const labor=hours*(Number(costsSettings.hourlyCost)||0),overhead=hours*(Number(costsSettings.overhead)||0);
 const costs=labor+overhead+consumables+travelCost+extraCost;
 const extras=roundMoney(roundMoney(Math.max(0,Number(job.travelPrice)||0))+extraCost);
 const net=roundMoney(serviceNet+extras),tax=roundMoney(net*(['small','exempt'].includes(job.taxMode??settings.taxMode)?0:(Number(job.tax??settings.tax)||0))/100),gross=roundMoney(net+tax),profit=net-costs,margin=net?profit/net*100:0;
 const suggested=costs/(1-Math.min(90,Math.max(0,Number(costsSettings.targetMargin)||0))/100);
 return{serviceNet,hours,consumables,travelCost,extraCost,labor,overhead,costs,extras,net,tax,gross,profit,margin,suggested};
}
export function requiredEquipment(job){return [...new Set((job.lines||[]).flatMap(l=>services.find(s=>s.id===l.service)?.equipment||[]))].map(id=>equipment.find(e=>e.id===id))}
export function jobTasks(job){return [...new Set((job.lines||[]).flatMap(l=>services.find(s=>s.id===l.service)?.tasks||[]))]}
export function validISODate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const [year,month,day]=value.split('-').map(Number);if(year<1||month<1||month>12||day<1)return false;const leap=year%4===0&&(year%100!==0||year%400===0),days=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31];return day<=days[month-1]}
function appointmentRange(job){if(!validISODate(job.date)||typeof job.time!=='string'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(job.time))return null;const start=+new Date(`${job.date}T${job.time}:00`),duration=Number(job.duration);return Number.isFinite(start)&&Number.isFinite(duration)&&duration>0?{start,end:start+duration*3600000}:null}
export function conflicts(job,jobs){const range=appointmentRange(job);if(!range)return[];return jobs.filter(j=>j.id!==job.id&&!['Storniert','Erledigt'].includes(j.status)).filter(j=>{const other=appointmentRange(j);return other&&range.start<other.end&&range.end>other.start})}
export function radicalBlocked(job){if(!job.lines?.some(l=>l.service==='radical')||!job.date)return false;const m=Number(job.date.split('-')[1]);return m>=3&&m<=9}
export const roundMoney=n=>Math.round((Number(n)+Number.EPSILON)*100)/100;
export const cents=n=>Math.round((Number(n)||0)*100);
export function invoicePayments(invoice){if(Array.isArray(invoice.payments))return invoice.payments;return invoice.paid?[{id:'legacy-'+invoice.id,date:invoice.paid,amount:invoice.calc.gross,method:'Übernommen',note:'Zahlung aus Version 1'}]:[]}
export function invoiceBalance(invoice){const paid=cents(invoicePayments(invoice).reduce((a,p)=>a+p.amount,0)),total=cents(invoice.calc.gross);return {paid:paid/100,open:Math.max(0,total-paid)/100,settled:paid>=total,partial:paid>0&&paid<total}}
export function recordPayment(invoice,payment){if(!validISODate(payment.date)||payment.date>today())throw Error('Bitte ein gültiges Zahlungsdatum bis heute angeben.');const amount=cents(payment.amount),balance=invoiceBalance(invoice);if(!Number.isFinite(Number(payment.amount))||amount<=0)throw Error('Zahlungsbetrag muss größer als null sein.');if(amount>cents(balance.open))throw Error('Zahlung ist höher als der offene Betrag.');invoice.payments=invoicePayments(invoice).map(p=>({...p}));invoice.payments.push({...payment,amount:amount/100});const updated=invoiceBalance(invoice);invoice.paid=updated.settled?[...invoice.payments].sort((a,b)=>a.date.localeCompare(b.date)).at(-1).date:'';return updated}
export function financials(state,period){const invoices=state.invoices.filter(i=>!period||i.issued.startsWith(period));const payments=state.invoices.flatMap(i=>{let cumulativeGross=0,cumulativeNet=0;return invoicePayments(i).map(p=>{const gross=roundMoney(p.amount);cumulativeGross=roundMoney(cumulativeGross+gross);const nextNet=roundMoney(cumulativeGross*(i.calc.gross?i.calc.net/i.calc.gross:1)),net=roundMoney(nextNet-cumulativeNet);cumulativeNet=nextNet;return {...p,invoiceId:i.id,number:i.number,customer:i.customer,paid:p.date,calc:{gross,net,tax:roundMoney(gross-net)}}})}).filter(p=>!period||p.date.startsWith(period));const expenses=state.expenses.filter(e=>!period||e.date.startsWith(period));const netRevenue=roundMoney(payments.reduce((a,p)=>a+p.calc.net,0)),cash=roundMoney(payments.reduce((a,p)=>a+p.calc.gross,0)),expenseNet=roundMoney(expenses.reduce((a,ex)=>a+ex.gross/(1+ex.tax/100),0)),outgoing=roundMoney(expenses.reduce((a,ex)=>a+ex.gross,0));const deductibleExpenses=roundMoney(expenses.reduce((a,ex)=>a+expenseCost(ex,state.settings),0));return {invoices,payments,expenses,netRevenue,cash,expenseNet,outgoing,deductibleExpenses,cashBalance:roundMoney(cash-outgoing),result:roundMoney(netRevenue-deductibleExpenses),open:roundMoney(state.invoices.reduce((a,i)=>a+invoiceBalance(i).open,0))}}
export function expenseCost(expense,settings=defaults){return roundMoney((expense.taxMode??settings.taxMode)==='standard'?expense.gross/(1+expense.tax/100):expense.gross)}
export function trackedHours(state,jobId){return (state.timeEntries||[]).filter(t=>t.jobId===jobId).reduce((sum,t)=>sum+Math.max(0,t.minutes),0)/60}
export function actualResult(state,job){const plan=calculate(job,job.costSettings??state.settings),time=(state.timeEntries||[]).filter(t=>t.jobId===job.id),expenses=state.expenses.filter(ex=>ex.jobId===job.id);const hasTime=time.length>0||job.actualTimeComplete===true,hasExpenses=expenses.length>0||job.actualCostsComplete===true,hours=hasTime?trackedHours(state,job.id):plan.hours;const expenseTotal=hasExpenses?expenses.reduce((sum,ex)=>sum+expenseCost(ex,state.settings),0):plan.consumables+plan.extraCost+plan.travelCost;const costs=hours*((job.costSettings??state.settings).hourlyCost+(job.costSettings??state.settings).overhead)+expenseTotal;const invoice=(state.invoices||[]).find(i=>i.jobId===job.id),invoiced=Boolean(invoice),revenue=invoiced?invoice.calc.net:plan.net;return {plan,revenue,invoiced,hours,costs:roundMoney(costs),profit:roundMoney(revenue-costs),margin:revenue?(revenue-costs)/revenue*100:0,hasTime,hasExpenses,complete:job.actualTimeComplete===true&&job.actualCostsComplete===true,expenseTotal:roundMoney(expenseTotal)}}
export function migrateState(input){const s=structuredClone(input);s.version=3;s.settings={...defaults,...s.settings,serviceRates:{...defaults.serviceRates,...s.settings?.serviceRates}};s.quotes??=[];if(!input.settings?.taxMode)s.settings.taxMode=Number(input.settings?.tax)===0?'exempt':'standard';s.timeEntries??=[];s.activeTimer??=null;for(const j of s.jobs){j.taxMode??=Number(j.tax)===0?'exempt':'standard';j.photos??=[];j.checks??=[];j.date??='';j.time??='';j.routeFrom??='';j.routeTo??='';j.siteDetails??={}}for(const ex of s.expenses)ex.taxMode??=s.settings.taxMode;for(const i of s.invoices){i.payments=invoicePayments(i).map(p=>({...p}));i.job.taxMode??=Number(i.job.tax)===0?'exempt':'standard';i.company.taxMode??=i.job.taxMode;i.job.siteDetails??={}}for(const q of s.quotes)if(q.job)q.job.siteDetails??={};return s}
export function annualWatch(state,year=state.settings.watchYear||new Date().getFullYear()){const f=financials(state,String(year)),previous=financials(state,String(year-1)).netRevenue+Math.max(0,Number(state.settings.previousTurnover)||0),turnover=f.netRevenue+Math.max(0,Number(state.settings.externalTurnover)||0),start=state.settings.businessStart?.slice(0,4)===String(year),limit=start?25000:100000;return {year,turnover,previous,start,limit,remaining:Math.max(0,limit-turnover),exceeded:turnover>limit,priorExceeded:!start&&previous>25000,nextYearRisk:turnover>25000,percent:Math.min(100,turnover/limit*100),reserve:roundMoney(Math.max(0,f.result)*(Number(state.settings.reservePercent)||0)/100),financials:f}}
export function copyFollowUp(job,date){return {...structuredClone(job),id:uid(),date,status:'Geplant',checks:[],photos:[],created:today(),parentJob:job.id,actualTimeComplete:false,actualCostsComplete:false,notes:job.notes||''}}

export function removePayment(invoice,paymentId){const entries=invoicePayments(invoice);if(!entries.some(p=>p.id===paymentId))throw Error('Zahlung nicht gefunden.');invoice.payments=entries.filter(p=>p.id!==paymentId).map(p=>({...p}));const balance=invoiceBalance(invoice);invoice.paid=balance.settled&&invoice.payments.length?[...invoice.payments].sort((a,b)=>a.date.localeCompare(b.date)).at(-1).date:'';return balance}
